import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Import(ResearchFixture.class)
class ExportTrialWorkflowTest {
    @Autowired ExportTrialService service;@Autowired ExportTrialWorker worker;@Autowired ExportTrialRepository store;@Autowired VersionIdentity identity;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired LocalFixtureLoader loader;@Autowired LocalAnnotationDependencies data;@Autowired ResearchFixture research;@Autowired MockMvc mvc;@Autowired TrialFileStore files;@Autowired StructuredExportWriter writer;@Autowired TrialUploadService uploads;
    @SpyBean LocalFinalReviewDependencies deps;@SpyBean ExportTrialRepository audit;
    String finalId;
    @BeforeEach void setup()throws Exception{reset(deps,audit);clean();loader.run(null);finalId=research.create(true).path("version").path("id").asText();}
    @AfterEach void after(){reset(deps,audit);clean();}
    void clean(){for(String t:List.of("trial_correction_rounds","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","snapshot_object_owners","annotation_version_snapshots","annotation_versions","annotation_case_counters","workflow_records"))jdbc.update("DELETE FROM "+t);}
    com.argument.version.port.VersionIdentity.Actor creator(){return identity.authenticate("Bearer dev-creator-li");}
    ObjectNode command(String format){var n=mapper.createObjectNode().put("format",format);n.putArray("finalVersionIds").add(finalId);n.putArray("include");return n;}
    ObjectNode create(String format){return service.create(creator(),VersionJson.uuid(),command(format));}
    ObjectNode ticket(ObjectNode record,String key){return service.ticket(creator(),record.path("id").asText(),false,key,mapper.createObjectNode().put("purpose","研究复核"),VersionJson.uuid());}
    int count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
    @Test void jsonExportsImmutableCompleteResourcesAndRetriesDoNotDuplicate()throws Exception{String key=VersionJson.uuid();var record=service.create(creator(),key,command("JSON"));assertThat(record.path("status").asText()).isEqualTo("QUEUED");assertThat(worker.processOne()).isTrue();assertThat(worker.processOne()).isFalse();var ready=service.read(creator(),record.path("id").asText());assertThat(ready.path("status").asText()).isEqualTo("COMPLETED");assertThat(service.create(creator(),key,command("JSON"))).isEqualTo(record);assertThat(count("trial_exports")).isEqualTo(1);var tk=ticket(record,VersionJson.uuid());byte[] bytes=service.content(creator(),tk.path("fileId").asText(),tk.path("downloadToken").asText()).bytes();var exported=mapper.readTree(bytes);assertThat(exported.path("elements").size()).isEqualTo(2);assertThat(exported.path("relations").size()).isEqualTo(1);assertThat(exported.path("participants").size()).isEqualTo(2);assertThat(exported.path("labels").size()).isEqualTo(15);assertThat(exported.path("provenance").size()).isGreaterThan(2);assertThat(exported.toString()).doesNotContain("decisionDigest","password","tokenDigest");Files.write(Path.of("target/member-d-export.json"),bytes);}
    @Test void xlsxIsAnActualWorkbookWithSafeInlineStringsAndLosslessLongText()throws Exception{var bundle=store.input(create("XLSX").path("id").asText());String text="=SUM(1,2)\n<&>"+"判决😀".repeat(16000);((ObjectNode)bundle.path("textVersions").get(0)).put("normalizedText",text);byte[] bytes=writer.write(bundle,"XLSX");var parts=new HashMap<String,String>();try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){for(ZipEntry e;(e=zip.getNextEntry())!=null;)parts.put(e.getName(),new String(zip.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}assertThat(parts).containsKeys("[Content_Types].xml","xl/workbook.xml","xl/_rels/workbook.xml.rels");var parser=DocumentBuilderFactory.newInstance();parser.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);for(var entry:parts.entrySet())parser.newDocumentBuilder().parse(new ByteArrayInputStream(entry.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThat(parts.values()).anyMatch(s->s.contains("@LongText:"));assertThat(parts.values()).noneMatch(s->s.contains("<f>"));Files.write(Path.of("target/member-d-export.xlsx"),bytes);Files.writeString(Path.of("target/member-d-export-long-text.txt"),text);}
    @Test void downloadGetIsReadOnlyRepeatableAndKeepsTheSameBytes(){var r=create("JSON");worker.processOne();String key=VersionJson.uuid();var tk=ticket(r,key);assertThat(ticket(r,key)).isEqualTo(tk);int events=count("trial_data_events"),downloads=count("trial_downloads");var first=service.content(creator(),tk.path("fileId").asText(),tk.path("downloadToken").asText());assertThat(service.content(creator(),tk.path("fileId").asText(),tk.path("downloadToken").asText()).bytes()).isEqualTo(first.bytes());assertThat(count("trial_downloads")).isEqualTo(downloads);assertThat(count("trial_data_events")).isEqualTo(events);String raw=jdbc.queryForObject("SELECT encrypted_result FROM trial_export_receipts WHERE operation_key=?",String.class,"EX05:"+r.path("id").asText());assertThat(raw).doesNotContain(tk.path("downloadToken").asText());}
    @Test void expiredWrongFileWrongActorAndTamperedContentAreRejected(){var r=create("JSON");worker.processOne();var tk=ticket(r,VersionJson.uuid());String file=tk.path("fileId").asText(),token=tk.path("downloadToken").asText();assertThatThrownBy(()->service.content(creator(),VersionJson.uuid(),token)).isInstanceOf(BusinessException.class).hasMessageContaining("不匹配");assertThatThrownBy(()->service.content(identity.authenticate("Bearer dev-admin-wang"),file,token)).isInstanceOf(BusinessException.class).hasMessageContaining("当前身份");var d=store.ticket(VersionJson.sha256(token));d.put("expiresAt","2000-01-01T00:00:00Z");jdbc.update("UPDATE trial_downloads SET payload_json=? WHERE id=?",d.toString(),d.path("id").asText());assertThatThrownBy(()->service.content(creator(),file,token)).isInstanceOf(BusinessException.class).hasMessageContaining("过期");var fresh=ticket(r,VersionJson.uuid());var f=store.file(file);f.put("sha256","0".repeat(64));jdbc.update("UPDATE trial_files SET payload_json=? WHERE id=?",f.toString(),file);assertThatThrownBy(()->service.content(creator(),file,fresh.path("downloadToken").asText())).isInstanceOf(BusinessException.class).hasMessageContaining("完整性");}
    @Test void permissionsAreRecheckedForEveryReadRetryAndTicket(){var r=create("JSON");worker.processOne();for(String token:List.of("dev-annotator-chen","dev-arbiter-zhao","dev-expert-qian"))assertThatThrownBy(()->service.read(identity.authenticate("Bearer "+token),r.path("id").asText())).isInstanceOf(BusinessException.class);var task=data.find("task",null,null).get(0);task.put("ownerUserId",VersionJson.uuid());data.replace("task",task);assertThatThrownBy(()->ticket(r,VersionJson.uuid())).isInstanceOf(BusinessException.class);assertThat(service.list(creator(),null,null,1,10).path("total").asInt()).isZero();}
    @Test void nonCommittedSourcesAndSpoofedFieldsCannotCreateAnExport()throws Exception{var finalVersion=jdbc.queryForObject("SELECT payload_json FROM final_annotation_versions WHERE id=?",String.class,finalId);var version=VersionJson.parse(mapper,finalVersion).put("status","APPROVED");jdbc.update("UPDATE final_annotation_versions SET payload_json=? WHERE id=?",version.toString(),finalId);assertThatThrownBy(()->create("JSON")).isInstanceOf(BusinessException.class).hasMessageContaining("已入库");assertThat(count("trial_exports")).isZero();var body=command("JSON").put("status","COMPLETED");var response=mvc.perform(post("/api/v1/exports").header("Authorization","Bearer dev-creator-li").header("Idempotency-Key",VersionJson.uuid()).contentType("application/json").content(body.toString())).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(400);}
    @Test void serializationFailureIsRecordedAndCannotIssueATicket(){var r=create("XLSX");var input=store.input(r.path("id").asText());((ObjectNode)input.path("elements").get(0)).put("text","bad\u0000text");jdbc.update("UPDATE trial_exports SET input_json=? WHERE id=?",input.toString(),r.path("id").asText());worker.processOne();assertThat(service.read(creator(),r.path("id").asText()).path("status").asText()).isEqualTo("FAILED");assertThat(count("trial_files")).isZero();assertThatThrownBy(()->ticket(r,VersionJson.uuid())).isInstanceOf(BusinessException.class).hasMessageContaining("尚未完成");}
    @Test void ticketAuditFailureRollsBackDownloadAndReceipt(){var r=create("JSON");worker.processOne();doThrow(new IllegalStateException("audit unavailable")).when(audit).event(any());assertThatThrownBy(()->ticket(r,VersionJson.uuid())).isInstanceOf(IllegalStateException.class);assertThat(count("trial_downloads")).isZero();assertThat(count("trial_export_receipts")).isEqualTo(1);}
    @Test void fileCannotBeOverwrittenAndPublicationRollsBackWithDatabaseFailure(){String id=VersionJson.uuid();files.publish(id,new byte[]{1});assertThatThrownBy(()->files.publish(id,new byte[]{2})).isInstanceOf(IllegalStateException.class);assertThat(files.read(id)).containsExactly((byte)1);var r=create("JSON");doThrow(new IllegalStateException("audit unavailable")).when(audit).event(any());assertThatThrownBy(worker::processOne).isInstanceOf(IllegalStateException.class);assertThat(store.export(r.path("id").asText(),false).path("status").asText()).isEqualTo("QUEUED");assertThat(count("trial_files")).isZero();}
    @Test void concurrentWorkersProduceOneFileAndCreationKeyIsConflictSafe()throws Exception{var r=create("JSON");var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->worker.processOne());var b=pool.submit(()->worker.processOne());a.get(15,TimeUnit.SECONDS);b.get(15,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertThat(count("trial_files")).isEqualTo(1);String key=VersionJson.uuid();service.create(creator(),key,command("JSON"));assertThatThrownBy(()->service.create(creator(),key,command("XLSX"))).isInstanceOf(BusinessException.class).hasMessageContaining("不同内容");}
 @Test void privateUploadIsImmutableAndDownloadsNeedOwnerAndPurpose(){var admin=identity.authenticate("Bearer dev-admin-wang");String key=VersionJson.uuid();var metadata=mapper.createObjectNode().put("fileName","原件.txt").put("mimeType","text/plain");byte[] bytes="法院原文".getBytes(java.nio.charset.StandardCharsets.UTF_8);var file=uploads.upload(admin,key,metadata,bytes,VersionJson.uuid());assertThat(file.has("storageKey")).isFalse();assertThat(uploads.upload(admin,key,metadata,bytes,VersionJson.uuid())).isEqualTo(file);assertThatThrownBy(()->uploads.upload(creator(),VersionJson.uuid(),metadata,bytes,VersionJson.uuid())).isInstanceOf(BusinessException.class);var tk=service.ticket(admin,file.path("id").asText(),true,VersionJson.uuid(),mapper.createObjectNode().put("purpose","核查原件"),VersionJson.uuid());assertThat(service.content(admin,file.path("id").asText(),tk.path("downloadToken").asText()).bytes()).isEqualTo(bytes);assertThatThrownBy(()->service.ticket(creator(),file.path("id").asText(),true,VersionJson.uuid(),mapper.createObjectNode().put("purpose","核查"),VersionJson.uuid())).isInstanceOf(BusinessException.class);assertThat(count("trial_files")).isEqualTo(1);}
 @Test void invalidUploadAndAuditFailureNeverPublishAFile(){var admin=identity.authenticate("Bearer dev-admin-wang");assertThatThrownBy(()->uploads.upload(admin,VersionJson.uuid(),mapper.createObjectNode().put("fileName","../原件.pdf").put("mimeType","application/pdf"),new byte[]{1},VersionJson.uuid())).isInstanceOf(BusinessException.class);assertThatThrownBy(()->uploads.upload(admin,VersionJson.uuid(),mapper.createObjectNode().put("fileName","原件.pdf").put("mimeType","application/pdf"),new byte[]{1},VersionJson.uuid())).isInstanceOf(BusinessException.class);doThrow(new IllegalStateException("audit unavailable")).when(audit).event(any());assertThatThrownBy(()->uploads.upload(admin,VersionJson.uuid(),mapper.createObjectNode().put("fileName","原件.txt").put("mimeType","text/plain"),new byte[]{65},VersionJson.uuid())).isInstanceOf(IllegalStateException.class);assertThat(count("trial_files")).isZero();}
    @Test void graphEndpointRejectsForgedBytesWrongRoleAndPublicFormatExpansion()throws Exception{
        var forged=command("SVG").put("svg","<svg/>");var response=mvc.perform(post("/api/local/member-d/graph-exports").header("Authorization","Bearer dev-creator-li").header("Idempotency-Key",VersionJson.uuid()).contentType("application/json").content(forged.toString())).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(400);
        assertThatThrownBy(()->service.create(creator(),VersionJson.uuid(),command("SVG"))).isInstanceOf(BusinessException.class);
        assertThatThrownBy(()->service.createGraph(identity.authenticate("Bearer dev-annotator-chen"),VersionJson.uuid(),command("PNG"))).isInstanceOf(BusinessException.class);
        var v=VersionJson.parse(mapper,jdbc.queryForObject("SELECT payload_json FROM final_annotation_versions WHERE id=?",String.class,finalId)).put("status","APPROVED");jdbc.update("UPDATE final_annotation_versions SET payload_json=? WHERE id=?",v.toString(),finalId);assertThatThrownBy(()->service.createGraph(creator(),VersionJson.uuid(),command("PNG"))).isInstanceOf(BusinessException.class);assertThat(count("trial_exports")).isZero();
    }

}
